import json, sys, os, glob
P = os.path.expanduser("~/.claude/projects/-Users-akima-workspace-claude-plugins--claude-worktrees-review-rally-1836fc/")
for f in sorted(glob.glob(P + "*.jsonl")):
    base = os.path.basename(f)
    if base.startswith("e2178b1f"):
        continue
    models = {}
    n = 0
    first_ts = last_ts = None
    rally_writes = 0
    reads = {}
    first_user = None
    for line in open(f, errors="replace"):
        try:
            o = json.loads(line)
        except Exception:
            continue
        n += 1
        ts = o.get("timestamp")
        if ts:
            first_ts = first_ts or ts
            last_ts = ts
        m = o.get("message") or {}
        if o.get("type") == "assistant":
            md = m.get("model")
            if md:
                models[md] = models.get(md, 0) + 1
            for c in (m.get("content") or []):
                if isinstance(c, dict) and c.get("type") == "tool_use":
                    inp = c.get("input") or {}
                    if c.get("name") == "Read":
                        fp = inp.get("file_path", "")
                        if "review-rally" in fp or "review-triage-loop" in fp:
                            reads[fp] = reads.get(fp, 0) + 1
                    s = json.dumps(inp, ensure_ascii=False)
                    if "rally.yaml" in s and c.get("name") in ("Write", "Bash", "Edit"):
                        rally_writes += 1
        if o.get("type") == "user" and first_user is None:
            ct = m.get("content")
            if isinstance(ct, str):
                first_user = ct[:150]
            elif isinstance(ct, list):
                for c in ct:
                    if isinstance(c, dict) and c.get("type") == "text":
                        first_user = c["text"][:150]; break
    print(base, "lines", n, first_ts, last_ts)
    print("  models", models)
    print("  rally_tool_calls", rally_writes)
    print("  first_user", repr(first_user))
    for k, v in sorted(reads.items()):
        print("  read", v, k)
EOF
